struct C {
  int n = 0;
  C& operator++() { ++n; return *this; }
  C operator++(int k) {
    std::printf("k=%d\n", k);
    C old = *this;
    ++n;
    return old;
  }
};

int main() {
  C c;
  c++;
  c.operator++(5);
  std::printf("%d\n", c.n);
}

